// --- Buyer config: edit these two lines for your business ---
const VIP_THRESHOLD = 500;
const BUSINESS_ALERT_EMAIL = "delivered@resend.dev";
// ----------------------------------------------------------------

const body = $json.body;
if (!body.customerName || !body.customerEmail || !body.items || body.totalValue == null) {
  throw new Error("Missing required order fields: customerName, customerEmail, items, totalValue");
}

const orderId = body.orderId || `ORD-${Date.now()}`;
const itemsSummary = Array.isArray(body.items)
  ? body.items.map((i) => (typeof i === "string" ? i : `${i.qty || 1}x ${i.name}`)).join(", ")
  : String(body.items);
const totalValue = Number(body.totalValue);
const isVip = totalValue >= VIP_THRESHOLD;

return {
  json: {
    orderId,
    customerName: body.customerName,
    customerEmail: body.customerEmail,
    itemsSummary,
    totalValue,
    currency: body.currency || "USD",
    isVip,
    businessAlertEmail: BUSINESS_ALERT_EMAIL
  }
};

